import express from 'express';
import { 
  getProducts, 
  getProductById, 
  createProduct, 
  updateProduct, 
  deleteProduct 
} from '../controllers/product.controllers.js';
import { protect, adminGuard } from '../middlewares/auth.middleware.js';

const router = express.Router();

// Public Routes
router.get('/', getProducts);
router.get('/:id', getProductById);

// Admin Protected Routes
router.post('/', protect, adminGuard, createProduct);
router.put('/:id', protect, adminGuard, updateProduct);
router.delete('/:id', protect, adminGuard, deleteProduct);

export default router;